style.css:
@-moz-document domain("google.com") {
/* Fondo de la página */
    body {
        background-image: url('https://i.postimg.cc/NGd6Kjrm/descarga-6.jpg') !important;
        background-size: cover !important;
        background-position: center !important;
        background-attachment: fixed !important;
        color: white !important;
    }

    /* Estilo de los enlaces */
    a {
        color: #f0c9d9 !important;
    }
    a:hover {
        color: #f1a7a0 !important;
    }

    /* Estilo de los botones */
    button, input[type="button"], input[type="submit"] {
        background-color: rgba(255, 255, 255, 0.2) !important;
        border: 1px solid #f0c9d9 !important;
        color: white !important;
    }

    /* Estilo de las cajas de búsqueda */
    input[type="text"] {
        background-color: rgba(255, 255, 255, 0.3) !important;
        border: 1px solid #f0c9d9 !important;
        color: white !important;
    }

    /* Bordes redondeados para las imágenes */
    img {
        border-radius: 10px !important;
    }

    /* Estilo del área de la barra de navegación */
    header {
        background-color: rgba(0, 0, 0, 0.6) !important;
    }

    /* Fondo del área principal */
    main {
        background-color: rgba(0, 0, 0, 0.5) !important;
    }
}
